<template>
  <AppLayout page-title="Assurance santé"><div class="hero-gradient mb-8" style="margin-bottom:var(--space-8)"><div style="position:relative;z-index:1"><p style="font-size:var(--font-size-sm);opacity:.85;margin-bottom:var(--space-2);font-weight:600;color:white">ESPACE ASSURANCE</p><h1 style="color:white;font-size:var(--font-size-3xl);font-weight:800;margin-bottom:var(--space-3)">Mes couvertures santé</h1><p style="color:white;opacity:.85;max-width:680px">Centralisez vos informations d’assurance et préparez les futurs formulaires numériques de CareLink. Aucun formulaire officiel n’est intégré à ce stade.</p></div></div>
    <div v-if="message" class="alert" :class="error ? 'alert-error' : 'alert-success'" style="margin-bottom:16px">{{ message }}</div>
    <div class="grid-2" style="align-items:start"><section class="card"><div class="section-header"><div><h3>Mes assurances</h3><p class="text-muted">Cartes, numéros d’adhérent et périodes de validité.</p></div><button class="btn btn-primary" @click="showForm = !showForm">{{ showForm ? 'Fermer' : '+ Ajouter' }}</button></div>
      <form v-if="showForm" class="form-grid" style="margin-bottom:20px" @submit.prevent="addInsurance"><div class="form-group"><label class="form-label">Organisme</label><select v-model="form.providerId" class="input" required><option value="">Sélectionner</option><option v-for="p in providers" :key="p.id" :value="p.id">{{ p.name }} ({{ p.code }})</option></select></div><div class="form-group"><label class="form-label">N° police</label><input v-model.trim="form.policyNumber" class="input" required autocomplete="off" /></div><div class="form-group"><label class="form-label">N° adhérent / assuré</label><input v-model.trim="form.memberId" class="input" required autocomplete="off" /></div><div class="form-group"><label class="form-label">Taux par défaut (%)</label><input v-model.number="form.coverageRate" class="input" type="number" min="0" max="100" step="0.01" required /></div><div class="form-group"><label class="form-label">Valide du</label><input v-model="form.validFrom" class="input" type="date" required /></div><div class="form-group"><label class="form-label">Valide jusqu’au</label><input v-model="form.validUntil" class="input" type="date" required /></div><div style="grid-column:1/-1;display:flex;gap:10px;justify-content:flex-end"><button type="button" class="btn btn-ghost" @click="showForm=false">Annuler</button><button class="btn btn-primary" :disabled="saving">{{ saving ? 'Enregistrement…' : 'Enregistrer' }}</button></div></form>
      <div v-if="loading" class="loading-overlay"><div class="spinner" /></div><div v-else-if="insurances.length === 0" class="empty-state"><div class="empty-icon">🛡️</div><div class="empty-title">Aucune assurance enregistrée</div><p>Ajoutez votre couverture pour pouvoir l’utiliser plus tard dans les parcours de soins.</p></div><div v-else class="stack"><article v-for="item in insurances" :key="item.id" class="insurance-card"><div class="insurance-card-head"><div><strong>{{ item.provider?.name || 'Organisme d’assurance' }}</strong><div class="text-muted">{{ item.provider?.code || '—' }}</div></div><span class="badge" :class="isValid(item.valid_until) ? 'badge-green' : 'badge-red'">{{ isValid(item.valid_until) ? 'Valide' : 'Expirée' }}</span></div><div class="insurance-meta"><div><span>N° police</span><b>{{ item.policy_number }}</b></div><div><span>N° assuré</span><b>{{ item.member_id }}</b></div><div><span>Couverture</span><b>{{ Number(item.coverage_rate_default).toLocaleString('fr-FR') }} %</b></div><div><span>Validité</span><b>{{ formatDate(item.valid_from) }} → {{ formatDate(item.valid_until) }}</b></div></div></article></div></section>
      <section class="card"><div class="section-header"><div><h3>Formulaires numériques</h3><p class="text-muted">La base technique est prête.</p></div><span class="badge badge-neutral">Préparation</span></div><div class="info-panel"><div class="info-icon">📄</div><div><strong>Un moteur de formulaires versionné est maintenant prévu dans CareLink.</strong><p>Il permettra plus tard de charger un modèle autorisé, ses versions, ses champs interactifs et ses règles de validation sans modifier les données déjà enregistrées.</p></div></div><div class="feature-list"><div>✓ Champs interactifs</div><div>✓ Pré-remplissage des données patient</div><div>✓ Versions de formulaires indépendantes</div><div>✓ Positionnement précis pour une future mise en page</div><div>✓ Brouillon puis soumission</div><div>✓ Traçabilité et contrôle d’accès</div></div><p class="text-muted" style="margin-top:16px;font-size:var(--font-size-xs)">Aucun document INAM officiel n’est distribué, copié ou déclaré officiel par cette version.</p></section></div>
  </AppLayout>
</template>
<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';import AppLayout from '@/components/layout/AppLayout.vue';import {supabase} from '@/lib/supabase';import {useAuthStore} from '@/stores/auth';interface Provider{id:string;name:string;code:string}interface Insurance{id:string;policy_number:string;member_id:string;coverage_rate_default:number;valid_from:string;valid_until:string;provider?:Provider}const authStore=useAuthStore(),providers=ref<Provider[]>([]),insurances=ref<Insurance[]>([]),loading=ref(true),saving=ref(false),showForm=ref(false),message=ref(''),error=ref(false),form=reactive({providerId:'',policyNumber:'',memberId:'',coverageRate:80,validFrom:'',validUntil:''});function formatDate(value:string){return new Date(value+'T00:00:00').toLocaleDateString('fr-FR')}function isValid(value:string){return value>=new Date().toISOString().slice(0,10)}async function load(){if(!authStore.user)return;loading.value=true;const [{data:providerData},{data:insuranceData,error:insuranceError}]=await Promise.all([supabase.from('insurance_providers').select('id,name,code').eq('is_active',true).order('name'),supabase.from('patient_insurances').select('id,policy_number,member_id,coverage_rate_default,valid_from,valid_until,provider:insurance_providers(id,name,code)').eq('patient_id',authStore.user.id).order('created_at',{ascending:false})]);providers.value=(providerData??[]) as Provider[];insurances.value=(insuranceData??[]) as unknown as Insurance[];if(insuranceError){error.value=true;message.value=insuranceError.message}loading.value=false}async function addInsurance(){if(!authStore.user)return;saving.value=true;message.value='';error.value=false;const {error:insertError}=await supabase.from('patient_insurances').insert({patient_id:authStore.user.id,provider_id:form.providerId,policy_number:form.policyNumber,member_id:form.memberId,coverage_rate_default:form.coverageRate,valid_from:form.validFrom,valid_until:form.validUntil});if(insertError){error.value=true;message.value=insertError.message}else{message.value='Assurance enregistrée.';showForm.value=false;Object.assign(form,{providerId:'',policyNumber:'',memberId:'',coverageRate:80,validFrom:'',validUntil:''});await load()}saving.value=false}onMounted(load)</script>
<style scoped>.section-header{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:18px}.section-header h3{margin-bottom:4px}.text-muted{color:var(--color-text-sub);font-size:var(--font-size-sm)}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.form-group{display:flex;flex-direction:column;gap:6px}.insurance-card{border:1px solid var(--color-border);border-radius:var(--radius-lg);padding:16px;background:var(--color-neutral-50)}.insurance-card-head{display:flex;justify-content:space-between;gap:12px;margin-bottom:16px}.insurance-meta{display:grid;grid-template-columns:1fr 1fr;gap:12px}.insurance-meta div{display:flex;flex-direction:column;gap:2px}.insurance-meta span{font-size:var(--font-size-xs);color:var(--color-text-muted)}.insurance-meta b{font-size:var(--font-size-sm);word-break:break-word}.info-panel{display:flex;gap:14px;padding:16px;border:1px solid var(--color-primary-100);background:var(--color-primary-50);border-radius:var(--radius-lg)}.info-icon{font-size:28px}.info-panel p{margin-top:6px;color:var(--color-text-sub);font-size:var(--font-size-sm)}.feature-list{display:grid;gap:10px;margin-top:18px;color:var(--color-text-sub);font-size:var(--font-size-sm)}.stack{display:grid;gap:12px}@media(max-width:700px){.form-grid,.insurance-meta{grid-template-columns:1fr}.section-header{flex-direction:column}.section-header .btn{width:100%}}</style>
